import{G as e,W as t,n,rt as r}from"./chunks/framework.DBm3e_pg.js";var i=JSON.parse(`{"title":"Về Sentinéz","description":"","frontmatter":{},"headers":[],"relativePath":"vi/about.md","filePath":"vi/about.md"}`),a={name:`vi/about.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="ve-sentinez" tabindex="-1">Về Sentinéz <a class="header-anchor" href="#ve-sentinez" aria-label="Permalink to “Về Sentinéz”">​</a></h1><blockquote><p><strong>Author:</strong> Hồ Đức Hưng<br><strong>Organization:</strong> Sentinez<br><strong>Version:</strong> v1.0<br><strong>Date:</strong> 2025-12-06</p></blockquote><p><em><strong>Sentinez</strong></em>, viết cách điệu <em><strong>Sentinéz</strong></em> là một chuỗi phần mềm cho cơ sở hạ tầng đám mây, được viết bằng các ngôn ngữ như Go, Rust, Java.</p><h2 id="lich-su" tabindex="-1">Lịch sử <a class="header-anchor" href="#lich-su" aria-label="Permalink to “Lịch sử”">​</a></h2><p>Được sáng lập bởi @kyerans (Duc Hung Ho) vào tháng 1/2025 khi đang học tập tại Trường đại học Bách Khoa, Đại học quốc gia Hồ Chí Minh (HCMUT-VNUHCM) và làm việc tại phòng điện toán đám mây, Công ty cổ phần giải pháp thanh toán Việt Nam (VNPAY)</p><h2 id="ve-sentinez-stack" tabindex="-1">Về Sentinéz Stack <a class="header-anchor" href="#ve-sentinez-stack" aria-label="Permalink to “Về Sentinéz Stack”">​</a></h2><p>Chuỗi ứng dụng này gồm có:</p><ul><li><strong>Sentinez Edge</strong> máy chủ proxy ngược, nơi tiếp nhận các yêu cầu và phản hồi ở lớp biên, trực tiếp của người dùng, tích hợp các tính năng bảo mật cho địa chỉ web đồng thời bảo vệ kết nối bằng TLS</li><li><strong>API Server</strong> cung cấp các api tương tác từ người dùng lên hệ thống của sentinez</li><li><strong>Realtime</strong> cho phép streaming data thông qua websocket từ hệ thống tới người dùng</li><li><strong>Catinat</strong> giải pháp cung cấp dịch vụ theo dõi hệ thống, được viết bằng ngôn ngữ Java mạnh mẽ.</li></ul><p>Ngoài ra, Sentinez còn phát triển 1 số công cụ để bảo vệ hạ tầng web ở mức độ sâu hơn</p><ul><li><strong>Etheral</strong>, viết cách điệu <em><strong>Étheral</strong></em>, là một bản proxy ngược được viết bằng ngôn ngữ Rust mạnh mẽ và an toàn cho bộ nhớ</li><li><strong>Quadrum</strong> cung cấp các cơ chế mạnh mẽ để theo dõi và thực hiện các giải pháp bảo vệ ở sâu L3/L4, trong khi hệ thống Sentinez bảo vệ người dùng chủ yếu ở L7 trong mô hình OSI</li></ul><h2 id="tinh-nang" tabindex="-1">Tính năng <a class="header-anchor" href="#tinh-nang" aria-label="Permalink to “Tính năng”">​</a></h2><p>Sentinez cung cấp cho người dùng các chứng năng bảo mật website tiêu biểu</p><ul><li>Rule-based do người dùng tạo, dùng để cảnh báo, chặn các request trực tiếp</li><li>WAF cung cấp bởi OWASP corerulesets, 1 tập hợp rules dùng để lọc request một cách hiệu quả</li><li>Các rule limit để chống lại các cuộc tấn công DDOS</li><li>Lọc các package và chặn các IP độc hại ngay ở L3/L4</li><li>Cung cấp các monitor rule giúp cảnh báo sớm các mối nguy hiểm</li><li>Bảo mật website và routing địa chỉ website bằng TLS/SSL</li></ul><h2 id="cloud-native" tabindex="-1">Cloud Native <a class="header-anchor" href="#cloud-native" aria-label="Permalink to “Cloud Native”">​</a></h2><p>Tất cả các ứng dụng được biên dịch và ảo hóa bằng Docker, với kích thước của mỗi image siêu nhẹ, cho phép các lập trình viên có thể tối ưu việc lưu trữ và triển khai lên các hạ tầng đám mây nhanh chóng bằng Docker, Docker compose hay Kubernetes</p><h2 id="hieu-suat-cao" tabindex="-1">Hiệu suất cao <a class="header-anchor" href="#hieu-suat-cao" aria-label="Permalink to “Hiệu suất cao”">​</a></h2><p>Đa phần các ứng dụng được viết và biên dịch bằng Go, ngôn ngữ native mạnh mẽ từ Google, sử dụng các công nghệ tiên tiến nhất của thời điểm hiện tại (ProtocolBuffer, gRPC Ecosystem) mang đến hiệu suất và sự mở rộng nhanh chóng kèm theo là độ trễ được đánh giá tương đối thấp, Sentinez cung cấp yêu cầu triển khai nhanh chóng trên bất kì cụm máy chủ nào và vẫn giữ được trạng thái ổn định.</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};